// CSD_RATIONALE_BEGIN
// Root cause analysis of the 52% ceiling (best attempt 43):
//
// The IsCompletePrefix early-close check in the main loop is the primary culprit.
// When the parser sees a minimal `SELECT col FROM table` sequence, it flags it as
// complete and we immediately close. This prevents the model from generating
// necessary WHERE/JOIN/GROUP BY clauses, causing the 141+ mode_A failures
// (syntax-valid but semantically wrong).
//
// The model's EOS token is a better stopping signal than greedy IsCompletePrefix.
// When the model finishes its intended SQL, it generates EOS. We should defer
// to that signal rather than preempting it with parser completeness.
//
// Secondary issue: repetition loops (3 examples in last attempt) exhaust budget
// on repeated column references. A 150-constrained-step cap stops this before
// the budget is consumed.
//
// Key changes vs best (52%):
// 1. Remove IsCompletePrefix early-close from main loop. Let model generate until
//    EOS or the 150-step constrained cap.
// 2. Use CloseSpanWithinBudget exclusively for closure; it tracks the longest
//    complete prefix and closes there—even if the model overshot with repetition.
// 3. Reduce preamble from 5 to 3 steps to recover budget for constrained SQL.
// 4. Updated guidance: discourage table-qualified column notation (dogs.age → age)
//    and unnecessary AS aliases, which appear in most failing rollout examples.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 (preamble): Loop guard includes !insideConstrainedOut, so the body runs
//   only when insideConstrainedOut is false (implication vacuously true). We only
//   set insideConstrainedOut := true on RenderedEndsWith, simultaneously setting
//   currentConstrainedOut := [] which satisfies IsValidPrefix([]) by method
//   precondition. On EOS break, insideConstrainedOut stays false; invariant holds.
//
// Phase 2 (OpenConstrainedSpan): Only reached when !insideConstrainedOut. The
//   helper postcondition sets currentConstrainedOut := [] and insideConstrainedOut
//   := true; IsValidPrefix([]) holds by method precondition.
//
// Phase 3 (main constrained loop): GroupBoostedConstrainedStep returns either EOS
//   (we break without appending, invariant unchanged) or a parser-valid next token.
//   AppendConstrainedToken extends currentConstrainedOut by one valid token,
//   preserving IsValidPrefix by the parser extension postcondition.
//
// Phase 4 (CloseSpanWithinBudget): Postcondition guarantees
//   insideOut ==> parser.IsValidPrefix(currentOut).
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: Each UnconstrainedStep costs +1 step and appends at most 1 token
//   (0 on EOS, 1 otherwise). Per iteration: |generated| grows by at most 1,
//   steps grows by exactly 1; invariant preserved.
// Phase 2: OpenConstrainedSpan costs +1 step and appends exactly 1 "<<" token.
//   |generated| grows by 1, steps grows by 1; invariant preserved.
// Phase 3: GroupBoostedConstrainedStep always costs +1 step. On EOS, no token
//   is appended (break path). Otherwise, AppendConstrainedToken appends exactly
//   1 token. Net: steps grows by 1 per at most 1 token appended each iteration;
//   invariant preserved.
// Phase 4: CloseSpanWithinBudget postcondition states
//   |generatedOut| <= |generated_before| + closeBudget. steps_after =
//   steps_before + closeBudget. By transitivity,
//   |generated_after| <= |generatedPrefix| + steps_after. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Generate a valid SQL SELECT query answering the question. Use column names directly WITHOUT table prefixes (write 'age' not 'dogs.age', write 'name' not 't.name'). Avoid AS aliases unless the schema uses them. When multiple tables are needed use explicit JOIN...ON. Include WHERE, GROUP BY, HAVING, ORDER BY, LIMIT when the question requires them. Keep the SQL concise. Output only the SQL placed between << and >>.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 3 steps) for "SQL: " prefix
while steps < maxSteps && steps < 3 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force open constrained span if not already inside one
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL under hard parser control with schema-token boosting.
// NO IsCompletePrefix early-close: let the model signal completion via EOS.
// Cap at 150 constrained steps to prevent repetition loops from consuming budget.
var constrainedSteps: nat := 0;
while steps < maxSteps && insideConstrainedOut && constrainedSteps < 150
  invariant 0 <= steps <= maxSteps
  invariant 0 <= constrainedSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
  var next := helpers.GroupBoostedConstrainedStep(
    lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, eosToken
  );
  steps := steps + 1;
  constrainedSteps := constrainedSteps + 1;
  if next == eosToken {
    break;
  } else {
    var ag, ai, ac := helpers.AppendConstrainedToken(
      lm, parser, generated, currentConstrainedOut, next
    );
    generated := ag;
    insideConstrainedOut := ai;
    currentConstrainedOut := ac;
  }
}

// Phase 4: Close constrained span using CloseSpanWithinBudget.
// This tracks the longest complete parse and emits ">>" there, handling both
// the EOS-terminated case (span is complete, closes immediately) and the
// step-cap case (repetition overshot, backtracks to last complete prefix).
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 200 {
    closeBudget := remaining;
  } else {
    closeBudget := 200;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

